mapper.select:
SELECT id, user_id, token, tenant_key, expires_at, resend_count, last_resend_at, created_at
FROM public.magic_link_tokens
WHERE token = #{token}

mapper.update:
UPDATE public.magic_link_tokens
SET resend_count = resend_count + 1,
last_resend_at = #{now}
WHERE user_id = #{userId}

mapper.select:
SELECT COUNT(*)
FROM public.magic_link_tokens
WHERE user_id = #{userId}
AND last_resend_at >= #{since}
